import React from 'react';

export type LinkVariant = 'quiet' | 'expressive' | 'nocturne';

export interface LinkProps extends Omit<React.AnchorHTMLAttributes<HTMLAnchorElement>, 'ping'> {
  variant?: LinkVariant;
  external?: boolean;
}

export function Link({
  variant = 'quiet',
  external = false,
  children,
  className = '',
  ...rest
}: LinkProps) {
  // Anchor ping is intentionally unsupported: it sends a hidden request on activation.
  const { ping: ignoredPing, ...safeRest } = rest as typeof rest & { ping?: string };
  void ignoredPing;
  let theme =
    'text-neutral-900 hover:text-neutral-600 underline underline-offset-4 decoration-neutral-300 hover:decoration-neutral-900';
  if (variant === 'expressive') {
    theme =
      'text-[#2547E8] hover:text-[#1E3CCD] font-medium underline underline-offset-4 decoration-[#2547E8]/40 hover:decoration-[#2547E8]';
  } else if (variant === 'nocturne') {
    theme =
      'text-white hover:text-neutral-300 underline underline-offset-4 decoration-neutral-700 hover:decoration-white';
  }

  return (
    <a
      className={`inline-flex items-center gap-1 transition-colors ${theme} ${className}`}
      target={external ? '_blank' : undefined}
      rel={external ? 'noopener noreferrer' : undefined}
      {...safeRest}
    >
      {children}
      {external && (
        <svg className="w-3 h-3 opacity-70" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"
          />
        </svg>
      )}
    </a>
  );
}

import React from 'react';
import { Link } from './index.js';

export function LinkPreview() {
  return (
    <div className="p-8 flex gap-6 justify-center bg-[#FAF9F6]">
      <Link variant="quiet" href="/docs">Documentation</Link>
      <Link variant="expressive" href="https://github.com/danishgm-sketch/Tessellate/tree/main/packages" external>Explore packages</Link>
      <Link variant="nocturne" href="https://github.com/danishgm-sketch/Tessellate/releases">Releases</Link>
    </div>
  );
}
